import { BLOCK_RIGIDITIES, BLOCK_TYPES, DEFAULT_AGENDA_SETTINGS, RESPONSIBILITY_AREAS } from "./constants.js";
import { createSession, now, uid } from "./models.js";

const DAY_MS=86400000;
let visibleWeek=null;
let activeAgendaContext=null;
let dayPlanRotation=0;
const esc=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[char]));
const localDate=value=>{const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const monday=value=>{const d=new Date(value);d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d};
const addDays=(value,amount)=>{const d=new Date(value);d.setDate(d.getDate()+amount);return d};
const minutes=time=>{const [h,m]=String(time||"00:00").split(":").map(Number);return h*60+m};
const duration=block=>Math.max(0,minutes(block.endTime)-minutes(block.startTime));
const formatTime=value=>String(value||"").slice(0,5);
const label=(map,key)=>map[key]||key||"—";

function defaultRecurrences(){return [
 {name:"Período individual",responsibilityArea:"pessoal",blockType:"protected",rigidity:"semiFlexible",daysOfWeek:[1,2,3,4,5],startTime:"05:00",endTime:"06:00"},
 {name:"Rotina do Júlio - manhã",responsibilityArea:"familia",blockType:"presence",rigidity:"rigid",daysOfWeek:[1,2,3,4,5],startTime:"06:00",endTime:"07:30"},
 {name:"Levar Júlio à escola",responsibilityArea:"familia",blockType:"fixed",rigidity:"rigid",daysOfWeek:[1,2,3,4,5],startTime:"07:30",endTime:"07:50"},
 {name:"Exercício corporal",responsibilityArea:"pessoal",blockType:"protected",rigidity:"semiFlexible",daysOfWeek:[1,2,3,4,5],startTime:"08:00",endTime:"09:00"},
 {name:"Período com Júlio",responsibilityArea:"familia",blockType:"presence",rigidity:"rigid",daysOfWeek:[1,2,3,4,5],startTime:"15:00",endTime:"18:00"},
 {name:"Rotina noturna do Júlio",responsibilityArea:"familia",blockType:"presence",rigidity:"rigid",daysOfWeek:[1,2,3,4,5,6,0],startTime:"19:00",endTime:"20:00"},
 {name:"Terapia",responsibilityArea:"pessoal",blockType:"fixed",rigidity:"rigid",daysOfWeek:[2],startTime:"14:30",endTime:"15:30"},
 {name:"Fisioterapia",responsibilityArea:"pessoal",blockType:"fixed",rigidity:"rigid",daysOfWeek:[1,3,5],startTime:"11:30",endTime:"13:00",endDate:"2026-08-31"},
 {name:"Reservável para clientes",responsibilityArea:"geld",blockType:"reservable",rigidity:"semiFlexible",daysOfWeek:[1,2,3,4,5],startTime:"18:00",endTime:"20:00"},
 {name:"Reservável para clientes - sábado",responsibilityArea:"geld",blockType:"reservable",rigidity:"semiFlexible",daysOfWeek:[6],startTime:"08:00",endTime:"14:00"}
].map(item=>({id:uid(),startDate:null,endDate:null,active:true,createdAt:now(),updatedAt:now(),...item}))}

function defaultMaintenance(){const rows=[["Tirar lixo","daily",1,10],["Lavar louça","daily",1,20],["Limpar e ativar robô","daily",1,15],["Guardar objetos fora do lugar","daily",1,15],["Manutenção rápida de pias e vasos","daily",1,15],["Regar plantas","daily",1,10],["Tirar pó e limpar móveis","weekly",3,25],["Lavar banheiros","weekly",1,60],["Passar pano nos pisos","weekly",1,45],["Mercado","weekly",1,60],["Preparar comida da semana","weekly",1,90],["Trocar toalhas","weekly",1,15],["Trocar roupa de cama","monthly",2,25]];return rows.map(([title,type,count,estimatedMinutes])=>({id:uid(),title,responsibilityArea:"casa",frequency:{type,count},estimatedMinutes,preferredDays:[],completedDates:[],lastCompletedAt:null,active:true,createdAt:now(),updatedAt:now()}))}

function routinePeriod(date,type){
 const point=new Date(date);point.setHours(0,0,0,0);
 if(type==="daily")return{start:point,end:addDays(point,1)};
 if(type==="monthly")return{start:new Date(point.getFullYear(),point.getMonth(),1),end:new Date(point.getFullYear(),point.getMonth()+1,1)};
 const start=monday(point);return{start,end:addDays(start,7)}
}
export function routineProgress(routine,date=new Date()){
 const type=routine.frequency?.type||"weekly",required=Math.max(1,Number(routine.frequency?.count||1)),period=routinePeriod(date,type);
 const completedDates=[...new Set(routine.completedDates||[])].filter(key=>{const value=new Date(`${key}T12:00:00`);return value>=period.start&&value<period.end});
 return{type,required,completed:completedDates.length,remaining:Math.max(0,required-completedDates.length),period,completedDates,due:completedDates.length<required}
}
export function dueMaintenanceRoutines(db,date=new Date()){return db.maintenanceRoutines.filter(routine=>routine.active&&routineProgress(routine,date).due).map(routine=>({...routine,progress:routineProgress(routine,date)}))}
export function recommendMaintenanceRoutines(db,date,availableMinutes){
 const point=new Date(date),weekday=point.getDay(),available=Math.max(0,Number(availableMinutes||0));
 const ranked=dueMaintenanceRoutines(db,point).map(routine=>{const progress=routine.progress,typeWeight=routine.frequency?.type==="daily"?300:routine.frequency?.type==="weekly"?180:100,preferred=routine.preferredDays?.map(Number).includes(weekday)?120:0,periodLength=Math.max(1,progress.period.end-progress.period.start),elapsed=Math.max(0,Math.min(1,(point-progress.period.start)/periodLength)),urgency=Math.round(elapsed*100)+(progress.remaining/progress.required)*50;return{...routine,recommendationScore:typeWeight+preferred+urgency}}).sort((a,b)=>b.recommendationScore-a.recommendationScore||Number(a.estimatedMinutes||0)-Number(b.estimatedMinutes||0));
 const selected=[];let remaining=available;for(const routine of ranked){const estimate=Math.max(1,Number(routine.estimatedMinutes||1));if(estimate<=remaining){selected.push(routine);remaining-=estimate}}
 return{pending:ranked,selected,totalMinutes:selected.reduce((sum,item)=>sum+Number(item.estimatedMinutes||0),0),availableMinutes:available}
}

export function ensureAgendaData(db){db.scheduleBlocks=Array.isArray(db.scheduleBlocks)?db.scheduleBlocks:[];db.scheduleRecurrences=Array.isArray(db.scheduleRecurrences)?db.scheduleRecurrences:[];db.maintenanceRoutines=Array.isArray(db.maintenanceRoutines)?db.maintenanceRoutines:[];db.agendaHistory=Array.isArray(db.agendaHistory)?db.agendaHistory:[];db.agendaSettings={...structuredClone(DEFAULT_AGENDA_SETTINGS),...(db.agendaSettings||{}),responsibilities:{...structuredClone(DEFAULT_AGENDA_SETTINGS.responsibilities),...(db.agendaSettings?.responsibilities||{})}};if(!db.agendaSettings.initialized){db.scheduleRecurrences.push(...defaultRecurrences());db.maintenanceRoutines.push(...defaultMaintenance());db.agendaSettings.initialized=true;db.agendaSettings.initializedAt=now()}return db}

function recurrenceOccurs(recurrence,date){const key=localDate(date);if(!recurrence.active||!recurrence.daysOfWeek?.includes(date.getDay()))return false;if(recurrence.startDate&&key<recurrence.startDate)return false;if(recurrence.endDate&&key>recurrence.endDate)return false;return true}
export function blocksForWeek(db,reference=new Date()){const start=monday(reference),end=addDays(start,7),manual=db.scheduleBlocks.filter(block=>block.date>=localDate(start)&&block.date<localDate(end)),overrides=new Set(manual.filter(block=>block.recurrenceId).map(block=>`${block.recurrenceId}:${block.originalOccurrenceDate||block.date}`)),virtual=[];for(let day=0;day<7;day++){const date=addDays(start,day),dateKey=localDate(date);for(const recurrence of db.scheduleRecurrences){if(!recurrenceOccurs(recurrence,date)||overrides.has(`${recurrence.id}:${dateKey}`))continue;virtual.push({id:`rec:${recurrence.id}:${dateKey}`,title:recurrence.name,responsibilityArea:recurrence.responsibilityArea,blockType:recurrence.blockType,rigidity:recurrence.rigidity,date:dateKey,startTime:recurrence.startTime,endTime:recurrence.endTime,recurrenceId:recurrence.id,status:"planned",allowNextAction:recurrence.blockType==="focus",source:"recurrence",confirmedExternalEvent:recurrence.blockType==="fixed",notes:"",_virtual:true})}}return [...manual,...virtual].filter(block=>!["cancelled","moved"].includes(block.status)).sort((a,b)=>`${a.date}${a.startTime}`.localeCompare(`${b.date}${b.startTime}`))}

function agendaHistory(db,type,block,extra={}){db.agendaHistory.push({id:uid(),type,blockId:block.id,title:block.title,date:block.date,at:now(),...extra})}
export function saveAgendaBlock(db,data){const existing=data.id&&!String(data.id).startsWith("rec:")?db.scheduleBlocks.find(block=>block.id===data.id):null,stamp=now(),block={id:existing?.id||uid(),title:data.title?.trim()||label(BLOCK_TYPES,data.blockType),responsibilityArea:data.responsibilityArea||"pessoal",blockType:data.blockType||"focus",rigidity:data.rigidity||"flexible",date:data.date||localDate(new Date()),startTime:data.startTime||"09:00",endTime:data.endTime||"10:00",recurrenceId:data.recurrenceId||null,originalOccurrenceDate:data.originalOccurrenceDate||null,status:data.status||existing?.status||"planned",allowNextAction:data.blockType==="focus"||data.allowNextAction===true,source:data.source||"manual",confirmedExternalEvent:data.blockType==="fixed"||data.confirmedExternalEvent===true,notes:data.notes||"",createdAt:existing?.createdAt||stamp,updatedAt:stamp};if(existing)Object.assign(existing,block);else db.scheduleBlocks.push(block);agendaHistory(db,existing?"updated":"planned",block);return block}
export function recordUnplannedSessionInAgenda(db,session){
 if(!session||session.scheduleBlockId||session.result==="cancelada"||Number(session.executedMinutes||0)<=0)return null;
 const task=db.tasks.find(item=>item.id===session.taskId),responsibilityArea=task?.responsibilityArea;
 if(!responsibilityArea||!RESPONSIBILITY_AREAS[responsibilityArea])return null;
 const existing=db.scheduleBlocks.find(block=>block.sourceSessionId===session.id);
 if(existing){session.scheduleBlockId=existing.id;session.responsibilityArea=responsibilityArea;return existing}
 const start=new Date(session.startedAt),end=new Date(start.getTime()+Math.max(1,Number(session.executedMinutes||0))*60000);
 const time=value=>`${String(value.getHours()).padStart(2,"0")}:${String(value.getMinutes()).padStart(2,"0")}`;
 const block=saveAgendaBlock(db,{title:session.taskTitleSnapshot||task.title,responsibilityArea,blockType:"focus",rigidity:"flexible",date:localDate(start),startTime:time(start),endTime:time(end),status:session.result==="concluida"?"completed":"partiallyCompleted",allowNextAction:false,source:"unplanned-execution",notes:"Criado automaticamente a partir de uma sessão sem bloco planejado."});
 block.sourceSessionId=session.id;block.actualMinutes=Number(session.executedMinutes||0);
 session.scheduleBlockId=block.id;session.responsibilityArea=responsibilityArea;
 const plannedHistory=[...db.agendaHistory].reverse().find(item=>item.blockId===block.id&&item.type==="planned");
 if(plannedHistory)plannedHistory.type="recorded";
 agendaHistory(db,"execution",block,{sessionId:session.id,minutes:session.executedMinutes,unplanned:true});
 return block
}
export function saveAgendaRecurrence(db,data){const existing=db.scheduleRecurrences.find(item=>item.id===data.id),value={id:existing?.id||uid(),name:data.name||data.title||"Bloco recorrente",responsibilityArea:data.responsibilityArea||"pessoal",blockType:data.blockType||"protected",rigidity:data.rigidity||"semiFlexible",daysOfWeek:(data.daysOfWeek||[]).map(Number),startTime:data.startTime,endTime:data.endTime,startDate:data.startDate||null,endDate:data.endDate||null,active:data.active!==false,createdAt:existing?.createdAt||now(),updatedAt:now()};if(existing)Object.assign(existing,value);else db.scheduleRecurrences.push(value);return value}

function significant(block){return duration(block)>=30||block.blockType==="presence"||block.blockType==="fixed"}
function evaluationMoment(reference){
 const selectedStart=monday(reference),currentStart=monday(new Date()),selectedKey=localDate(selectedStart),currentKey=localDate(currentStart);
 if(selectedKey===currentKey)return new Date();
 if(selectedKey<currentKey){const end=addDays(selectedStart,7);end.setMilliseconds(-1);return end}
 return selectedStart
}
function sessionResponsibility(db,session){return session.responsibilityArea||db.tasks.find(task=>task.id===session.taskId)?.responsibilityArea||null}
function isExecutionBlock(block){return !["margin","reservable"].includes(block.blockType)&&block.source!=="unplanned-execution"}
export function executionStateForResponsibility(db,area,reference=new Date()){
 const start=monday(reference),end=addDays(start,7),evaluation=evaluationMoment(reference),futureWeek=localDate(start)>localDate(monday(new Date()));
 const weekBlocks=blocksForWeek(db,start).filter(block=>block.responsibilityArea===area&&isExecutionBlock(block));
 const elapsedBlocks=futureWeek?[]:weekBlocks.filter(block=>new Date(`${block.date}T${block.endTime}`)<=evaluation);
 const sessions=db.sessions.filter(session=>session.result!=="cancelada"&&Number(session.executedMinutes||0)>0&&sessionResponsibility(db,session)===area&&new Date(session.startedAt)>=start&&new Date(session.startedAt)<end&&new Date(session.startedAt)<=evaluation);
 const blockById=new Map(db.scheduleBlocks.map(block=>[block.id,block]));
 const sessionMinutes=sessions.reduce((sum,session)=>sum+Number(session.executedMinutes||0),0);
 const unplannedMinutes=sessions.filter(session=>!session.scheduleBlockId||blockById.get(session.scheduleBlockId)?.source==="unplanned-execution").reduce((sum,session)=>sum+Number(session.executedMinutes||0),0);
 const completedWithoutSessionMinutes=elapsedBlocks.filter(block=>block.status==="completed"&&!db.sessions.some(session=>session.scheduleBlockId===block.id&&session.result!=="cancelada")).reduce((sum,block)=>sum+duration(block),0);
 const actualMinutes=sessionMinutes+completedWithoutSessionMinutes;
 const expectedMinutes=elapsedBlocks.reduce((sum,block)=>sum+duration(block),0);
 const completedPlanMinutes=elapsedBlocks.reduce((sum,block)=>{const linked=db.sessions.filter(session=>session.scheduleBlockId===block.id&&session.result!=="cancelada").reduce((total,session)=>total+Number(session.executedMinutes||0),0);return sum+(block.status==="completed"?duration(block):Math.min(duration(block),linked))},0);
 const ratio=expectedMinutes?actualMinutes/expectedMinutes:null,compliance=expectedMinutes?completedPlanMinutes/expectedMinutes:null;
 let executionStatus="Sem planejamento",executionKind="neutral";
 if(expectedMinutes){if(ratio>=.8){executionStatus="Bem executada";executionKind="good"}else if(ratio>=.5){executionStatus="Em execução";executionKind="balanced"}else if(ratio>0){executionStatus="Pouco executada";executionKind="low"}else{executionStatus="Não executada";executionKind="attention"}}
 else if(actualMinutes){executionStatus="Execução registrada";executionKind="good"}
 else if(weekBlocks.length){executionStatus="Aguardando execução"}
 return{area,executionStatus,executionKind,actualMinutes,unplannedMinutes,plannedMinutes:actualMinutes-unplannedMinutes,completedWithoutSessionMinutes,expectedMinutes,completedPlanMinutes,ratio,compliance,hasFuture:weekBlocks.length>elapsedBlocks.length}
}
export function responsibilityStates(db,reference=new Date()){
 const current=blocksForWeek(db,reference),all=[...db.scheduleBlocks,...current.filter(block=>block._virtual)],today=evaluationMoment(reference);
 return Object.keys(RESPONSIBILITY_AREAS).map(area=>{const week=current.filter(block=>block.responsibilityArea===area&&!["cancelled","missed"].includes(block.status)&&block.blockType!=="reservable"),past=all.filter(block=>block.responsibilityArea===area&&block.blockType!=="reservable"&&significant(block)&&new Date(`${block.date}T${block.endTime}`)<=today).sort((a,b)=>`${b.date}${b.endTime}`.localeCompare(`${a.date}${a.endTime}`)),last=past[0],days=last?Math.floor((today-new Date(`${last.date}T12:00:00`))/DAY_MS):99,planned=week.reduce((sum,block)=>sum+duration(block),0),pendingMaintenance=area==="casa"?dueMaintenanceRoutines(db,today).length:0;let status="Em equilíbrio",kind="balanced";if(area==="familia"&&week.some(block=>block.blockType==="presence")){status="Bem cuidada";kind="good"}else if(pendingMaintenance>5||days>=7){status="Precisa de atenção";kind="attention"}else if(!week.length||days>=4){status="Pouco presente";kind="low"}else if(planned>=120){status="Bem cuidada";kind="good"}return{area,status,kind,last,days,planned,next:week.find(block=>new Date(`${block.date}T${block.startTime}`)>=today),pendingMaintenance,execution:executionStateForResponsibility(db,area,reference)}})
}

export function currentAgendaState(db,date=new Date()){const blocks=blocksForWeek(db,date),stamp=date.getTime(),current=blocks.find(block=>{const start=new Date(`${block.date}T${block.startTime}`).getTime(),end=new Date(`${block.date}T${block.endTime}`).getTime();return stamp>=start&&stamp<end}),next=blocks.find(block=>new Date(`${block.date}T${block.startTime}`).getTime()>stamp);return{current,next}}
function executedForBlock(db,id){return db.sessions.filter(session=>session.scheduleBlockId===id).reduce((sum,session)=>sum+Number(session.executedMinutes||0),0)}

function blockCard(db,block){const executed=executedForBlock(db,block.id),canAct=block.blockType==="focus"||block.blockType==="maintenance",isCasa=block.responsibilityArea==="casa",unplanned=block.source==="unplanned-execution";return `<article class="agenda-block type-${block.blockType} area-${block.responsibilityArea} status-${block.status} ${unplanned?"source-unplanned-execution":""}" data-agenda-block="${esc(block.id)}"><div class="agenda-block-head"><b>${esc(block.title)}</b><span>${formatTime(block.startTime)}–${formatTime(block.endTime)}</span></div><p>${esc(label(RESPONSIBILITY_AREAS,block.responsibilityArea))} · ${esc(label(BLOCK_TYPES,block.blockType))}</p>${unplanned?"<small class=\"unplanned-label\">Execução não planejada</small>":""}${executed?`<small>${executed} min executados</small>`:""}<div class="agenda-block-actions">${isCasa?`<button data-agenda-action="routines" data-id="${esc(block.id)}">Rotinas</button>`:canAct?`<button data-agenda-action="next" data-id="${esc(block.id)}">Próxima ação</button>`:""}<button data-agenda-action="edit" data-id="${esc(block.id)}">Editar</button><button data-agenda-action="duplicate" data-id="${esc(block.id)}">Duplicar</button>${block.blockType==="reservable"?`<button data-agenda-action="convert" data-id="${esc(block.id)}">Converter</button>`:""}<button data-agenda-action="partial" data-id="${esc(block.id)}">Parcial</button><button data-agenda-action="complete" data-id="${esc(block.id)}">Concluir</button><button data-agenda-action="delete" data-id="${esc(block.id)}">Excluir</button></div></article>`}
function weekGrid(db,reference){const start=monday(reference),blocks=blocksForWeek(db,start),startHour=db.agendaSettings.weekStartHour||5,endHour=db.agendaSettings.weekEndHour||23,slots=(endHour-startHour)*2,headers=Array.from({length:7},(_,index)=>{const date=addDays(start,index);return `<div class="agenda-day-head" style="grid-column:${index+2}"><b>${new Intl.DateTimeFormat("pt-BR",{weekday:"short"}).format(date)}</b><span>${date.getDate()}/${date.getMonth()+1}</span></div>`}).join(""),times=Array.from({length:endHour-startHour+1},(_,index)=>`<div class="agenda-time" style="grid-row:${index*2+2}/span 2">${String(startHour+index).padStart(2,"0")}:00</div>`).join(""),cards=blocks.map(block=>{const date=new Date(`${block.date}T12:00:00`),column=((date.getDay()+6)%7)+2,startSlot=Math.max(0,Math.round((minutes(block.startTime)-startHour*60)/30)),span=Math.max(1,Math.round(duration(block)/30));return `<div class="agenda-position" style="grid-column:${column};grid-row:${startSlot+2}/span ${span}">${blockCard(db,block)}</div>`}).join("");return `<div class="agenda-week-grid" style="--agenda-slots:${slots}"><div class="agenda-corner"></div>${headers}${times}${cards}</div>`}

function executionDetails(execution){const compliance=execution.compliance===null?"sem blocos vencidos":`${Math.round(execution.compliance*100)}% da Agenda`,outside=execution.unplannedMinutes?` · ${execution.unplannedMinutes} min fora do plano`:"";return `${execution.actualMinutes} min realizados${outside} · ${compliance}`}
function balanceCards(db,reference){return `<section class="agenda-balance"><div class="section-title"><h2>Como está sua semana?</h2><span class="subtle">planejamento e prática, separados</span></div><div class="agenda-balance-grid">${responsibilityStates(db,reference).map(item=>`<article class="balance-card ${item.kind} execution-${item.execution.executionKind}"><span class="responsibility-dot area-${item.area}"></span><div><b>${label(RESPONSIBILITY_AREAS,item.area)}</b><p><span>Planejamento</span><strong>${item.status}</strong></p><p><span>Execução</span><strong>${item.execution.executionStatus}</strong></p><small>${executionDetails(item.execution)}</small></div></article>`).join("")}</div></section>`}
function maintenanceFrequencyLabel(routine){const progress=routineProgress(routine,new Date()),period=routine.frequency?.type==="daily"?"dia":routine.frequency?.type==="weekly"?"semana":"mês";return `${progress.completed}/${progress.required} neste ${period} · ${routine.estimatedMinutes} min`}
function maintenanceRoutineModal(routine={}){
 const days=[1,2,3,4,5,6,0],modal=document.createElement("div");modal.className="modal-backdrop";modal.innerHTML=`<form class="modal maintenance-routine-modal"><div class="modal-head"><div><h2>${routine.id?"Editar rotina":"Nova rotina"}</h2><p class="subtle">A nova regra vale para as próximas pendências; o histórico realizado permanece.</p></div><button type="button" class="text-button" data-agenda-close>Fechar</button></div><div class="form-grid"><label class="wide">Nome<input required name="title" value="${esc(routine.title||"")}" placeholder="Ex.: Lavar banheiro"></label><label>Frequência<select name="frequencyType"><option value="daily" ${routine.frequency?.type==="daily"?"selected":""}>Diária</option><option value="weekly" ${!routine.frequency?.type||routine.frequency?.type==="weekly"?"selected":""}>Semanal</option><option value="monthly" ${routine.frequency?.type==="monthly"?"selected":""}>Mensal</option></select></label><label>Quantidade no período<input required type="number" min="1" max="31" name="frequencyCount" value="${routine.frequency?.count||1}"></label><label>Duração estimada (min)<input required type="number" min="5" step="5" name="estimatedMinutes" value="${routine.estimatedMinutes||30}"></label><fieldset class="context-field wide"><legend>Dias preferenciais</legend>${days.map(day=>`<label class="check"><input type="checkbox" name="preferredDays" value="${day}" ${routine.preferredDays?.map(Number).includes(day)?"checked":""}>${["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"][day]}</label>`).join("")}</fieldset></div><p class="form-error"></p><div class="modal-actions"><button type="button" class="secondary" data-agenda-close>Cancelar</button><button class="primary">Salvar rotina</button></div></form>`;document.body.append(modal);return modal
}
function bindMaintenanceRoutineModal(db,modal,routine,persist,render){
 modal.querySelectorAll("[data-agenda-close]").forEach(button=>button.addEventListener("click",()=>modal.remove()));modal.querySelector("form").addEventListener("submit",event=>{event.preventDefault();const data=new FormData(event.currentTarget),title=String(data.get("title")||"").trim(),error=event.currentTarget.querySelector(".form-error");if(!title){error.textContent="Informe o nome da rotina.";return}const values={title,frequency:{type:data.get("frequencyType"),count:Math.max(1,Number(data.get("frequencyCount")||1))},estimatedMinutes:Math.max(5,Number(data.get("estimatedMinutes")||30)),preferredDays:data.getAll("preferredDays").map(Number),updatedAt:now()};if(routine)Object.assign(routine,values);else db.maintenanceRoutines.push({id:uid(),responsibilityArea:"casa",completedDates:[],lastCompletedAt:null,active:true,createdAt:now(),...values});db.agendaHistory.push({id:uid(),type:routine?"maintenance-updated":"maintenance-created",routineId:routine?.id||db.maintenanceRoutines.at(-1).id,title,at:now()});persist();modal.remove();render()})
}
function maintenancePanel(db){const active=db.maintenanceRoutines.filter(item=>item.active),archived=db.maintenanceRoutines.filter(item=>!item.active);return `<section class="panel agenda-maintenance"><div class="section-title"><div><h2>Manutenção da Casa</h2><p class="subtle">Catálogo e cumprimento das rotinas no período atual.</p></div><button class="secondary" data-agenda-action="add-maintenance">Adicionar rotina</button></div><div class="maintenance-list">${active.map(item=>`<article data-maintenance-row="${item.id}"><label><input type="checkbox" data-maintenance-id="${item.id}" ${item.completedDates?.includes(localDate(new Date()))?"checked":""}><span>${esc(item.title)}</span><small>${maintenanceFrequencyLabel(item)}</small></label><div><button class="text-button" data-agenda-action="edit-maintenance" data-id="${item.id}">Editar</button><button class="text-button danger-text" data-agenda-action="delete-maintenance" data-id="${item.id}">Excluir</button></div></article>`).join("")||"<p class=\"empty-copy\">Nenhuma rotina ativa.</p>"}</div>${archived.length?`<details class="maintenance-archived"><summary>Ver excluídas (${archived.length})</summary><div>${archived.map(item=>`<article><span><b>${esc(item.title)}</b><small>${item.frequency?.count||1}× ${item.frequency?.type==="daily"?"ao dia":item.frequency?.type==="monthly"?"por mês":"por semana"}</small></span><button class="text-button" data-agenda-action="restore-maintenance" data-id="${item.id}">Restaurar</button></article>`).join("")}</div></details>`:""}</section>`}

function maintenanceSelectionModal(db,block){
 const available=Math.max(1,duration(block)-executedForBlock(db,block.id)),date=new Date(`${block.date}T12:00:00`),recommendation=recommendMaintenanceRoutines(db,date,available),planned=(block.plannedRoutineIds||[]).map(id=>recommendation.pending.find(item=>item.id===id)).filter(Boolean),preferred=planned.length?planned:recommendation.selected,selectedIds=new Set(preferred.map(item=>item.id)),selectedTotal=preferred.reduce((sum,item)=>sum+Number(item.estimatedMinutes||0),0);
 const modal=document.createElement("div");modal.className="modal-backdrop";modal.innerHTML=`<div class="modal maintenance-modal"><div class="modal-head"><div><h2>Rotinas para este bloco</h2><p class="subtle">${esc(block.title)} · ${available} min disponíveis</p></div><button class="text-button" data-agenda-close>Fechar</button></div>${recommendation.pending.length?`<div class="maintenance-recommendation-summary"><b>Seleção recomendada</b><span><strong data-maintenance-total>${selectedTotal}</strong> de ${available} min estimados</span></div><div class="maintenance-selection-list">${recommendation.pending.map(routine=>`<label class="${selectedIds.has(routine.id)?"":"maintenance-extra"}"><input type="checkbox" data-select-maintenance="${routine.id}" data-estimate="${routine.estimatedMinutes}" ${selectedIds.has(routine.id)?"checked":""}><span><b>${esc(routine.title)}</b><small>${routine.progress.completed}/${routine.progress.required} no período · faltam ${routine.progress.remaining}</small></span><em>${routine.estimatedMinutes} min</em></label>`).join("")}</div>${recommendation.pending.length>preferred.length?`<button class="text-button" data-show-all-maintenance>Ver todas as pendentes</button>`:""}<p class="form-error" data-maintenance-error></p><div class="modal-actions"><button class="secondary" data-agenda-close>Cancelar</button><button class="primary" data-start-maintenance ${block.date!==localDate(new Date())?"disabled":""}>Iniciar bloco</button></div>${block.date!==localDate(new Date())?"<p class=\"subtle\">A execução pode ser iniciada apenas na data planejada para o bloco.</p>":""}`:`<div class="empty-state compact"><h3>Rotinas em dia</h3><p>Nenhuma rotina está pendente para esta data.</p></div><div class="modal-actions"><button class="primary" data-agenda-close>Fechar</button></div>`}</div>`;document.body.append(modal);
 const refresh=()=>{const total=[...modal.querySelectorAll("[data-select-maintenance]:checked")].reduce((sum,input)=>sum+Number(input.dataset.estimate||0),0);modal.querySelector("[data-maintenance-total]")?.replaceChildren(String(total));const error=modal.querySelector("[data-maintenance-error]");if(error)error.textContent=total>available?`A seleção ultrapassa o bloco em ${total-available} min.`:"";const start=modal.querySelector("[data-start-maintenance]");if(start&&block.date===localDate(new Date()))start.disabled=!total||total>available};
 modal.querySelectorAll("[data-select-maintenance]").forEach(input=>input.addEventListener("change",refresh));modal.querySelector("[data-show-all-maintenance]")?.addEventListener("click",event=>{modal.querySelectorAll(".maintenance-extra").forEach(row=>row.classList.remove("maintenance-extra"));event.currentTarget.remove()});refresh();return modal
}
function startMaintenanceBlock(db,block,routineIds,persist,render){
 const remaining=Math.max(1,duration(block)-executedForBlock(db,block.id));
 db.currentSession=createSession({taskId:null,scheduleBlockId:block.id,taskTitleSnapshot:block.title,area:"organizacao",subarea:"geral",plannedMinutes:remaining,responsibilityArea:"casa",recommendationSource:"agenda_maintenance",maintenanceRoutineIds:routineIds,initialEnergy:db.preferences?.energy||2,availableContexts:db.preferences?.contexts||[]});
 block.status="inProgress";block.updatedAt=now();agendaHistory(db,"execution-started",block,{routineIds});persist();queueMicrotask(()=>{const home=document.querySelector('[data-action="navigate"][data-page="hoje"]');if(home)home.click();else render()})
}
function decorateMaintenanceFocus(db,persist){
 const session=db.currentSession;if(!session||session.recommendationSource!=="agenda_maintenance")return;
 const focus=document.querySelector(".focus"),timer=focus?.querySelector("#timer-display");if(!focus||!timer||focus.querySelector(".maintenance-focus-panel"))return;
 focus.querySelector('[data-result="concluida"]')?.replaceChildren("Concluir bloco Casa");
 const day=localDate(new Date(session.startedAt)),routines=(session.maintenanceRoutineIds||[]).map(id=>db.maintenanceRoutines.find(item=>item.id===id)).filter(Boolean),panel=document.createElement("section");panel.className="maintenance-focus-panel";panel.innerHTML=`<div><p class="eyebrow">ROTINAS SELECIONADAS</p><strong><span data-maintenance-done>${routines.filter(item=>item.completedDates?.includes(day)).length}</span> de ${routines.length} concluídas</strong></div><div class="maintenance-focus-list">${routines.map(routine=>`<label><input type="checkbox" data-complete-maintenance="${routine.id}" ${routine.completedDates?.includes(day)?"checked":""}><span>${esc(routine.title)}</span><small>${routine.estimatedMinutes} min estimados</small></label>`).join("")}</div></section>`;timer.after(panel);
 panel.querySelectorAll("[data-complete-maintenance]").forEach(input=>input.addEventListener("change",()=>{const routine=db.maintenanceRoutines.find(item=>item.id===input.dataset.completeMaintenance);if(!routine)return;routine.completedDates=[...new Set((routine.completedDates||[]).filter(date=>date!==day).concat(input.checked?[day]:[]))];routine.lastCompletedAt=input.checked?now():routine.lastCompletedAt;routine.updatedAt=now();panel.querySelector("[data-maintenance-done]").textContent=String(panel.querySelectorAll("[data-complete-maintenance]:checked").length);persist()}))
}
export function renderAgendaPage(db){ensureAgendaData(db);visibleWeek=visibleWeek||monday(new Date());const start=monday(visibleWeek),end=addDays(start,6);return `<section class="page-head compact agenda-head"><div><p class="eyebrow">PLANEJAMENTO DE ATENÇÃO</p><h1>Semana</h1><p class="subtle">${new Intl.DateTimeFormat("pt-BR",{day:"numeric",month:"short"}).format(start)} a ${new Intl.DateTimeFormat("pt-BR",{day:"numeric",month:"short",year:"numeric"}).format(end)}</p></div><div class="header-actions"><button class="secondary" data-agenda-action="prev-week">←</button><button class="secondary" data-agenda-action="today-week">Hoje</button><button class="secondary" data-agenda-action="next-week">→</button><button class="secondary" data-agenda-action="plan-day">Planejar o dia</button><button class="secondary" data-agenda-action="replan-day">Reorganizar hoje</button><button class="primary" data-agenda-action="new">Novo bloco</button></div></section>${balanceCards(db,start)}<section class="panel agenda-calendar"><div class="agenda-legend">${Object.entries(BLOCK_TYPES).map(([key,value])=>`<span class="type-${key}">${value}</span>`).join("")}</div>${weekGrid(db,start)}</section>${maintenancePanel(db)}`}

function agendaConflicts(db){const blocks=blocksForWeek(db,visibleWeek||new Date()).filter(block=>!["margin","reservable"].includes(block.blockType)),conflicts=[];for(let i=0;i<blocks.length;i++)for(let j=i+1;j<blocks.length;j++){const a=blocks[i],b=blocks[j];if(a.date===b.date&&minutes(a.startTime)<minutes(b.endTime)&&minutes(b.startTime)<minutes(a.endTime))conflicts.push([a,b])}return conflicts}
export function mountAgendaPage(db){const main=document.querySelector(".main-content");if(!main)return;main.innerHTML=renderAgendaPage(db);const conflicts=agendaConflicts(db);if(conflicts.length){const notice=document.createElement("div");notice.className="agenda-conflict-note";notice.innerHTML=`<b>${conflicts.length} conflito(s) para revisar</b><span>Nenhum bloco foi removido ou movido automaticamente.</span>`;main.querySelector(".agenda-calendar")?.before(notice)}}
export function augmentAgendaNavigation(page){document.querySelectorAll(".sidebar nav,.mobile-nav").forEach(nav=>{if(nav.querySelector('[data-page="semana"]'))return;const button=document.createElement("button");button.className=`nav-item ${page==="semana"?"active":""}`;button.dataset.action="navigate";button.dataset.page="semana";button.innerHTML="<span>▦</span>Semana";const config=nav.querySelector('[data-page="config"]');nav.insertBefore(button,config||null)})}
export function augmentTodayWithAgenda(db){const main=document.querySelector(".main-content");if(!main||main.querySelector("#agenda-today-bridge"))return;const {current,next}=currentAgendaState(db),states=responsibilityStates(db);const section=document.createElement("section");section.id="agenda-today-bridge";section.className="agenda-today-bridge";section.innerHTML=`<div class="section-title"><h2>Agenda de hoje</h2><button class="text-button" data-action="navigate" data-page="semana">Ver semana</button></div><div class="agenda-now-grid"><article class="panel"><p class="eyebrow">AGORA</p>${current?`<h2>${esc(current.title)}</h2><p>${label(RESPONSIBILITY_AREAS,current.responsibilityArea)} · ${label(BLOCK_TYPES,current.blockType)} até ${current.endTime}</p>${current.responsibilityArea==="casa"?`<button class="primary" data-agenda-action="routines" data-id="${esc(current.id)}">Rotinas</button>`:["focus","maintenance"].includes(current.blockType)?`<button class="primary" data-agenda-action="next" data-id="${esc(current.id)}">Escolher próxima ação</button>`:"<p class=\"subtle\">Este período protege presença e atenção.</p>"}`:"<h2>Sem bloco neste momento</h2><p class=\"subtle\">A margem também faz parte do planejamento.</p>"}</article><article class="panel"><p class="eyebrow">PRÓXIMO MARCO</p>${next?`<h2>${esc(next.title)}</h2><p>${new Intl.DateTimeFormat("pt-BR",{weekday:"short",day:"numeric"}).format(new Date(`${next.date}T12:00:00`))} · ${next.startTime}</p>`:"<h2>Semana aberta</h2><p class=\"subtle\">Nenhum compromisso próximo.</p>"}</article></div><div class="today-responsibilities">${states.map(item=>`<span class="${item.kind} execution-${item.execution.executionKind}"><strong>${label(RESPONSIBILITY_AREAS,item.area)}</strong><small>Planejamento</small><b>${item.status}</b><small>Execução</small><b>${item.execution.executionStatus}</b><em>${item.execution.actualMinutes} min${item.execution.unplannedMinutes?` · ${item.execution.unplannedMinutes} fora do plano`:""}</em></span>`).join("")}</div>`;main.prepend(section)}

function blockModal(block={}){const recurrence=block.recurrenceId?null:undefined,dayChecks=[1,2,3,4,5,6,0].map(day=>`<label class="check"><input type="checkbox" name="daysOfWeek" value="${day}">${["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"][day]}</label>`).join("");const el=document.createElement("div");el.className="modal-backdrop";el.innerHTML=`<form class="modal" id="agenda-block-form"><div class="modal-head"><h2>${block.id?"Editar bloco":"Novo bloco"}</h2><button type="button" class="text-button" data-agenda-close>Fechar</button></div><input type="hidden" name="id" value="${esc(block.id||"")}"><input type="hidden" name="recurrenceId" value="${esc(block.recurrenceId||"")}"><input type="hidden" name="originalOccurrenceDate" value="${esc(block._virtual?block.date:block.originalOccurrenceDate||"")}"><div class="form-grid"><label>Título<input name="title" value="${esc(block.title||"")}" placeholder="Ex.: Foco Geld"></label><label>Responsabilidade<select name="responsibilityArea">${Object.entries(RESPONSIBILITY_AREAS).map(([key,value])=>`<option value="${key}" ${block.responsibilityArea===key?"selected":""}>${value}</option>`).join("")}</select></label><label>Tipo<select name="blockType">${Object.entries(BLOCK_TYPES).map(([key,value])=>`<option value="${key}" ${block.blockType===key?"selected":""}>${value}</option>`).join("")}</select></label><label>Rigidez<select name="rigidity">${Object.entries(BLOCK_RIGIDITIES).map(([key,value])=>`<option value="${key}" ${block.rigidity===key?"selected":""}>${value}</option>`).join("")}</select></label><label>Data<input required type="date" name="date" value="${block.date||localDate(new Date())}"></label><label>Início<input required type="time" name="startTime" value="${block.startTime||"09:00"}"></label><label>Fim<input required type="time" name="endTime" value="${block.endTime||"10:00"}"></label><label class="wide">Observação<textarea name="notes">${esc(block.notes||"")}</textarea></label><fieldset class="context-field"><legend>Repetir semanalmente</legend><label class="check"><input type="checkbox" name="repeatWeekly"> Criar recorrência</label>${dayChecks}<label>Até<input type="date" name="endDate"></label></fieldset></div><p class="form-error"></p><div class="modal-actions"><button type="button" class="secondary" data-agenda-close>Cancelar</button><button class="primary">Salvar bloco</button></div></form>`;document.body.append(el);return el}
function findBlock(db,id){if(String(id).startsWith("rec:")){const date=String(id).match(/\d{4}-\d{2}-\d{2}$/)?.[0];return blocksForWeek(db,date?new Date(`${date}T12:00:00`):visibleWeek||new Date()).find(block=>block.id===id)}return db.scheduleBlocks.find(block=>block.id===id)}
function proposalModal(db){const states=responsibilityStates(db,visibleWeek||new Date()),start=monday(visibleWeek||new Date()),suggestions=[];const add=(day,startTime,endTime,area,type,title)=>suggestions.push({id:uid(),date:localDate(addDays(start,day)),startTime,endTime,responsibilityArea:area,blockType:type,rigidity:"flexible",title,status:"planned",allowNextAction:type==="focus",source:"suggestion"});if(!blocksForWeek(db,start).some(b=>b.responsibilityArea==="casa"))add(2,"13:00","13:40","casa","maintenance","Manutenção da Casa");const needy=states.filter(item=>["attention","low"].includes(item.kind)&&!["familia","casa"].includes(item.area)).slice(0,2);needy.forEach((item,index)=>add(3+index,"10:00","11:00",item.area,"focus",`Foco ${label(RESPONSIBILITY_AREAS,item.area)}`));add(3,"11:00","11:30","pessoal","margin","Margem preservada");const el=document.createElement("div");el.className="modal-backdrop";el.innerHTML=`<div class="modal"><div class="modal-head"><div><h2>Proposta para a semana</h2><p class="subtle">Revise antes de salvar. Nada foi confirmado ainda.</p></div><button class="text-button" data-agenda-close>Fechar</button></div><div class="proposal-list">${suggestions.map(item=>`<label><input type="checkbox" checked data-proposal-id="${item.id}"><span><b>${esc(item.title)}</b><small>${item.date} · ${item.startTime}–${item.endTime}</small></span></label>`).join("")||"<p class=\"empty-copy\">A semana já possui atenção distribuída.</p>"}</div><div class="modal-actions"><button class="secondary" data-agenda-close>Cancelar</button><button class="primary" data-accept-proposal>Aceitar selecionados</button></div></div>`;document.body.append(el);el.querySelector("[data-accept-proposal]")?.addEventListener("click",()=>{suggestions.filter(item=>el.querySelector(`[data-proposal-id="${item.id}"]`)?.checked).forEach(item=>saveAgendaBlock(db,item));el.remove();el.dispatchEvent(new CustomEvent("agenda-saved",{bubbles:true}))});return el}

const clock=value=>`${String(Math.floor(value/60)).padStart(2,"0")}:${String(value%60).padStart(2,"0")}`;
const planningMeta={
 familia:{title:"Presença com a família",blockType:"presence"},
 casa:{title:"Manutenção da Casa",blockType:"maintenance"},
 pessoal:{title:"Período pessoal",blockType:"protected"},
 profissional:{title:"Foco Profissional",blockType:"focus"},
 geld:{title:"Foco Geld",blockType:"focus"}
};
export function buildDayPlanProposals(db,reference=new Date(),rotation=0){
 const dateKey=localDate(reference),startHour=db.agendaSettings.weekStartHour||5,endHour=db.agendaSettings.weekEndHour||23,nowMinutes=reference.getHours()*60+reference.getMinutes(),horizonStart=Math.max(startHour*60,Math.ceil(nowMinutes/15)*15),horizonEnd=endHour*60;
 const existing=blocksForWeek(db,reference).filter(block=>block.date===dateKey).map(block=>({...block,_start:minutes(block.startTime),_end:minutes(block.endTime)})).filter(block=>block._end>horizonStart&&block._start<horizonEnd).sort((a,b)=>a._start-b._start);
 if(horizonStart>=horizonEnd)return{date:dateKey,horizonStart,horizonEnd,existing,proposals:[]};
 const occupied=[];for(const block of existing){const start=Math.max(horizonStart,block._start),end=Math.min(horizonEnd,block._end),last=occupied.at(-1);if(last&&start<=last.end)last.end=Math.max(last.end,end);else occupied.push({start,end})}
 const gaps=[];let cursor=horizonStart;for(const interval of occupied){if(interval.start>cursor)gaps.push({start:cursor,end:interval.start});cursor=Math.max(cursor,interval.end)}if(cursor<horizonEnd)gaps.push({start:cursor,end:horizonEnd});
 const states=responsibilityStates(db,reference),planningScore={attention:50,low:35,balanced:18,good:4},executionScore={attention:55,low:38,balanced:20,good:3,neutral:12},baseScores=Object.fromEntries(states.map(state=>[state.area,(planningScore[state.kind]||10)+(executionScore[state.execution.executionKind]||10)+Math.min(20,state.days||0)+(state.area==="casa"?dueMaintenanceRoutines(db,reference).length*5:0)])),allocated=Object.fromEntries(Object.keys(RESPONSIBILITY_AREAS).map(area=>[area,0])),allocatedRoutines=new Set(),proposals=[];
 const existingActive=existing.filter(block=>!["margin","reservable"].includes(block.blockType)).reduce((sum,block)=>sum+Math.max(0,Math.min(horizonEnd,block._end)-Math.max(horizonStart,block._start)),0),maximumActive=Math.round((horizonEnd-horizonStart)*(db.agendaSettings.maximumPlanningOccupancy||.75)),activeBudget=Math.max(0,maximumActive-existingActive);
 let proposedActive=0;
 const chooseArea=()=>Object.keys(RESPONSIBILITY_AREAS).map((area,index)=>({area,score:baseScores[area]-allocated[area]/6+((index+rotation)%5)*.01})).sort((a,b)=>b.score-a.score)[0].area;
 const houseSelection=available=>{const ranked=recommendMaintenanceRoutines(db,reference,available).pending.filter(routine=>!allocatedRoutines.has(routine.id));const selected=[];let remaining=available;for(const routine of ranked){const estimate=Math.max(1,Number(routine.estimatedMinutes||1));if(estimate<=remaining){selected.push(routine);remaining-=estimate}}return selected};
 for(const gap of gaps){let point=gap.start,activityStreak=0;while(gap.end-point>0){const remaining=gap.end-point,budgetLeft=activeBudget-proposedActive;if(remaining<30||activityStreak>=75||budgetLeft<30){const span=Math.min(15,remaining);proposals.push({id:uid(),date:dateKey,startTime:clock(point),endTime:clock(point+span),responsibilityArea:"pessoal",blockType:"margin",rigidity:"flexible",title:"Margem preservada",status:"planned",source:"day-plan",reason:"Margem para preservar transições e imprevistos.",routineIds:[]});point+=span;activityStreak=0;continue}
   let area=chooseArea(),span=Math.min(75,remaining,Math.floor(budgetLeft/15)*15),routineIds=[];if(span<30)continue;
   if(area==="casa"){const routines=houseSelection(span);if(routines.length){const routineMinutes=routines.reduce((sum,item)=>sum+Number(item.estimatedMinutes||0),0);span=Math.min(span,Math.max(15,Math.ceil(routineMinutes/15)*15));routineIds=routines.map(item=>item.id);routineIds.forEach(id=>allocatedRoutines.add(id))}else{baseScores.casa-=80;area=chooseArea()}}
   const meta=planningMeta[area],state=states.find(item=>item.area===area);proposals.push({id:uid(),date:dateKey,startTime:clock(point),endTime:clock(point+span),responsibilityArea:area,blockType:meta.blockType,rigidity:"flexible",title:meta.title,status:"planned",source:"day-plan",reason:area==="casa"?`${routineIds.length} rotina(s) pendente(s) cabem neste período.`:`Planejamento ${state.status.toLowerCase()} e execução ${state.execution.executionStatus.toLowerCase()}.`,routineIds});allocated[area]+=span;proposedActive+=span;activityStreak+=span;point+=span}}
 return{date:dateKey,horizonStart,horizonEnd,existing,proposals}
}
function dayPlanModal(db,persist,render,rotation=0){
 const plan=buildDayPlanProposals(db,new Date(),rotation),entries=[...plan.existing.map(block=>({kind:"existing",start:block._start,end:block._end,block})),...plan.proposals.map(block=>({kind:"proposal",start:minutes(block.startTime),end:minutes(block.endTime),block}))].sort((a,b)=>a.start-b.start),modal=document.createElement("div");modal.className="modal-backdrop";modal.innerHTML=`<div class="modal day-plan-modal"><div class="modal-head"><div><h2>Planejar o dia</h2><p class="subtle">${new Intl.DateTimeFormat("pt-BR",{dateStyle:"full"}).format(new Date(`${plan.date}T12:00:00`))} · a partir de ${clock(plan.horizonStart)}</p></div><button class="text-button" data-agenda-close>Fechar</button></div><div class="day-plan-summary"><b>${plan.existing.length} bloco(s) preservado(s)</b><span>${plan.proposals.length} proposta(s) para os intervalos livres</span></div><div class="day-plan-timeline">${entries.map(entry=>entry.kind==="existing"?`<article class="day-plan-row preserved"><span>${entry.block.startTime}–${entry.block.endTime}</span><div><b>${esc(entry.block.title)}</b><small>Preservado · ${label(RESPONSIBILITY_AREAS,entry.block.responsibilityArea)}</small></div></article>`:`<article class="day-plan-row proposed" data-day-proposal="${entry.block.id}"><input type="checkbox" checked data-day-select><div class="day-plan-times"><input type="time" data-day-start value="${entry.block.startTime}"><input type="time" data-day-end value="${entry.block.endTime}"></div><div><b>${esc(entry.block.title)}</b>${entry.block.blockType==="margin"?"":`<select data-day-area>${Object.entries(RESPONSIBILITY_AREAS).map(([key,value])=>`<option value="${key}" ${key===entry.block.responsibilityArea?"selected":""}>${value}</option>`).join("")}</select>`}<small>${esc(entry.block.reason)}${entry.block.routineIds?.length?` · ${entry.block.routineIds.length} rotina(s) selecionada(s)`:""}</small></div></article>`).join("")||"<div class=\"empty-state compact\"><h3>Dia sem intervalos disponíveis</h3><p>Não há horários futuros livres dentro da janela configurada.</p></div>"}</div><p class="form-error" data-day-plan-error></p><div class="modal-actions"><button class="secondary" data-agenda-close>Cancelar</button>${plan.proposals.length?`<button class="secondary" data-regenerate-day-plan>Gerar outra proposta</button><button class="primary" data-apply-day-plan>Aplicar planejamento do dia</button>`:""}</div></div>`;document.body.append(modal);
 const close=()=>modal.remove();modal.querySelectorAll("[data-agenda-close]").forEach(button=>button.addEventListener("click",close));modal.querySelector("[data-regenerate-day-plan]")?.addEventListener("click",()=>{close();dayPlanRotation++;dayPlanModal(db,persist,render,dayPlanRotation)});
 modal.querySelector("[data-apply-day-plan]")?.addEventListener("click",()=>{const selected=[];for(const row of modal.querySelectorAll("[data-day-proposal]")){if(!row.querySelector("[data-day-select]").checked)continue;const original=plan.proposals.find(item=>item.id===row.dataset.dayProposal),startTime=row.querySelector("[data-day-start]").value,endTime=row.querySelector("[data-day-end]").value,area=row.querySelector("[data-day-area]")?.value||original.responsibilityArea;if(minutes(endTime)<=minutes(startTime)){modal.querySelector("[data-day-plan-error]").textContent="Toda proposta precisa terminar depois de começar.";return}const meta=original.blockType==="margin"?{title:"Margem preservada",blockType:"margin"}:planningMeta[area];selected.push({...original,startTime,endTime,responsibilityArea:area,title:meta.title,blockType:meta.blockType})}
  const fixed=plan.existing.map(block=>({start:Math.max(plan.horizonStart,block._start),end:Math.min(plan.horizonEnd,block._end)})),ranges=[];for(const item of selected.sort((a,b)=>minutes(a.startTime)-minutes(b.startTime))){const range={start:minutes(item.startTime),end:minutes(item.endTime)};if([...fixed,...ranges].some(other=>range.start<other.end&&other.start<range.end)){modal.querySelector("[data-day-plan-error]").textContent="Há uma sobreposição entre propostas ou com um bloco preservado.";return}ranges.push(range)}
  selected.forEach(item=>{const block=saveAgendaBlock(db,item);block.plannedRoutineIds=item.routineIds||[]});persist();close();render()});return modal
}

export function addAgendaConfig(db){
ensureAgendaData(db);
const grid=document.querySelector(".settings-grid");if(!grid||grid.querySelector("#agenda-settings-panel"))return;const panel=document.createElement("section");panel.className="panel";panel.id="agenda-settings-panel";panel.innerHTML=`<h2>Agenda</h2><p class="subtle">A agenda distribui atenção e preserva margem.</p><label>Ocupação máxima (%)<input name="agendaOccupancy" type="number" min="60" max="90" value="${Math.round(db.agendaSettings.maximumPlanningOccupancy*100)}"></label><label>Margem mínima (min)<input name="agendaMargin" type="number" min="15" value="${db.agendaSettings.minimumMarginMinutes}"></label><label>Foco mínimo (min)<input name="agendaFocus" type="number" min="30" value="${db.agendaSettings.minimumFocusMinutes}"></label><label>Penalidade de troca de contexto<input name="agendaSwitch" type="number" min="0" value="${db.agendaSettings.contextSwitchPenalty}"></label><div class="responsibility-settings">${Object.entries(RESPONSIBILITY_AREAS).map(([key,value])=>`<label class="check"><input type="checkbox" name="responsibility-${key}" ${db.agendaSettings.responsibilities[key]?.active!==false?"checked":""}>${value}</label>`).join("")}</div>`;grid.append(panel)}
function decorateTaskModal(db,modal){const form=modal?.querySelector("#task-form");if(!form||form.querySelector('[name="responsibilityArea"]'))return;const id=form.querySelector('[name="id"]')?.value,task=db.tasks.find(item=>item.id===id),labelEl=document.createElement("label");labelEl.innerHTML=`Área de responsabilidade<select name="responsibilityArea"><option value="">Não classificada</option>${Object.entries(RESPONSIBILITY_AREAS).map(([key,value])=>`<option value="${key}" ${task?.responsibilityArea===key?"selected":""}>${value}</option>`).join("")}</select>`;form.querySelector('[name="area"]')?.closest("label")?.before(labelEl);form.addEventListener("submit",()=>queueMicrotask(()=>{const saved=id?db.tasks.find(item=>item.id===id):[...db.tasks].reverse().find(item=>item.title===form.querySelector('[name="title"]')?.value.trim());if(saved){saved.responsibilityArea=form.querySelector('[name="responsibilityArea"]')?.value||null;saved.updatedAt=now();localStorage.setItem("proxima-acao-db",JSON.stringify({...db,version:2}))}}))}

export function bindAgendaIntegration({db,persist,render,navigateToRecommendation,page}){document.querySelectorAll('[data-page="semana"]').forEach(button=>{if(button.dataset.agendaBound)return;button.dataset.agendaBound="1";button.addEventListener("click",()=>{})});document.querySelectorAll('[data-action="new-task"],[data-action="edit-task"]').forEach(button=>button.addEventListener("click",()=>queueMicrotask(()=>decorateTaskModal(db,document.querySelector(".modal-backdrop")))));document.querySelectorAll('[data-action="start-session"]').forEach(button=>button.addEventListener("click",()=>{if(db.currentSession&&activeAgendaContext){db.currentSession.scheduleBlockId=activeAgendaContext.scheduleBlockId;db.currentSession.responsibilityArea=activeAgendaContext.responsibilityArea;db.currentSession.recommendationSource="agenda";persist()}}));decorateMaintenanceFocus(db,persist);
const activeSessionId=db.currentSession?.id,activeScheduleBlockId=db.currentSession?.scheduleBlockId;document.querySelectorAll('[data-action="finish-session"]').forEach(button=>button.addEventListener("click",()=>{const session=db.sessions.find(item=>item.id===activeSessionId);if(!session)return;if(!activeScheduleBlockId){if(recordUnplannedSessionInAgenda(db,session))persist();return}const block=db.scheduleBlocks.find(item=>item.id===activeScheduleBlockId);if(block){block.actualMinutes=executedForBlock(db,block.id);if(button.dataset.result==="concluida")block.status="completed";else if(["avancou","interrompida"].includes(button.dataset.result))block.status="partiallyCompleted";block.updatedAt=now();agendaHistory(db,"execution",block,{sessionId:session.id,minutes:session.executedMinutes});persist()}}));
document.querySelectorAll("[data-agenda-close]").forEach(button=>button.addEventListener("click",()=>button.closest(".modal-backdrop")?.remove()));document.querySelectorAll("[data-agenda-action]").forEach(button=>button.addEventListener("click",()=>{
const action=button.dataset.agendaAction,id=button.dataset.id;let block=findBlock(db,id);
if(action==="new"){const modal=blockModal();bindModal(modal)}else if(action==="edit"&&block){const modal=blockModal(block);bindModal(modal)}else if(action==="duplicate"&&block){saveAgendaBlock(db,{...block,id:null,recurrenceId:null,originalOccurrenceDate:null,title:`${block.title} (cópia)`});persist();render()}else if(action==="delete"&&block&&confirm(`Excluir "${block.title}"?`)){if(block._virtual)saveAgendaBlock(db,{...block,id:null,status:"cancelled",originalOccurrenceDate:block.date});else db.scheduleBlocks=db.scheduleBlocks.filter(item=>item.id!==block.id);agendaHistory(db,"cancelled",block);persist();render()}else if(action==="complete"&&block){if(block._virtual)block=saveAgendaBlock(db,{...block,id:null,originalOccurrenceDate:block.date});block.status="completed";block.updatedAt=now();agendaHistory(db,"completed",block);persist();render()}else if(action==="partial"&&block){if(block._virtual)block=saveAgendaBlock(db,{...block,id:null,originalOccurrenceDate:block.date});block.status="partiallyCompleted";block.updatedAt=now();agendaHistory(db,"partiallyCompleted",block);persist();render()}else if(action==="convert"&&block){if(block._virtual)block=saveAgendaBlock(db,{...block,id:null,originalOccurrenceDate:block.date});block.blockType="fixed";block.rigidity="rigid";block.confirmedExternalEvent=true;block.title=prompt("Título do compromisso",block.title)||block.title;block.updatedAt=now();agendaHistory(db,"converted",block);persist();render()}
else if(action==="routines"&&block){if(block._virtual)block=saveAgendaBlock(db,{...block,id:null,originalOccurrenceDate:block.date});const modal=maintenanceSelectionModal(db,block);modal.querySelectorAll("[data-agenda-close]").forEach(close=>close.addEventListener("click",()=>modal.remove()));modal.querySelector("[data-start-maintenance]")?.addEventListener("click",()=>{const ids=[...modal.querySelectorAll("[data-select-maintenance]:checked")].map(input=>input.dataset.selectMaintenance);if(!ids.length)return;modal.remove();startMaintenanceBlock(db,block,ids,persist,render)})}
else if(action==="next"&&block){if(block._virtual)block=saveAgendaBlock(db,{...block,id:null,originalOccurrenceDate:block.date});activeAgendaContext={scheduleBlockId:block.id,responsibilityArea:block.responsibilityArea,availableMinutes:Math.max(15,Math.min(60,duration(block)-executedForBlock(db,block.id)))};persist();navigateToRecommendation(activeAgendaContext)}
else if(action==="prev-week"){visibleWeek=addDays(visibleWeek||new Date(),-7);render()}else if(action==="next-week"){visibleWeek=addDays(visibleWeek||new Date(),7);render()}else if(action==="today-week"){visibleWeek=monday(new Date());render()}else if(action==="plan-day"){dayPlanModal(db,persist,render,dayPlanRotation)}else if(action==="replan-day"){const today=localDate(new Date()),movable=db.scheduleBlocks.filter(item=>item.date===today&&item.status==="planned"&&item.rigidity==="flexible");if(!movable.length){alert("Não há blocos flexíveis restantes para reorganizar hoje.");return}if(confirm(`Mover ${movable.length} bloco(s) flexível(is) para amanhã, preservando os rígidos?`)){movable.forEach(item=>{agendaHistory(db,"moved",item,{fromDate:item.date});item.date=localDate(addDays(new Date(`${item.date}T12:00:00`),1));item.status="moved";const copy=saveAgendaBlock(db,{...item,id:null,status:"planned",source:"replan"});copy.movedFromId=item.id});persist();render()}}else if(action==="add-maintenance"){const modal=maintenanceRoutineModal();bindMaintenanceRoutineModal(db,modal,null,persist,render)}else if(action==="edit-maintenance"){const routine=db.maintenanceRoutines.find(item=>item.id===id);if(routine){const modal=maintenanceRoutineModal(routine);bindMaintenanceRoutineModal(db,modal,routine,persist,render)}}else if(action==="delete-maintenance"){const routine=db.maintenanceRoutines.find(item=>item.id===id);if(routine&&confirm(`Excluir "${routine.title}" das rotinas ativas? O histórico será preservado.`)){routine.active=false;routine.updatedAt=now();db.agendaHistory.push({id:uid(),type:"maintenance-deactivated",routineId:routine.id,title:routine.title,at:now()});persist();render()}}else if(action==="restore-maintenance"){const routine=db.maintenanceRoutines.find(item=>item.id===id);if(routine){routine.active=true;routine.updatedAt=now();db.agendaHistory.push({id:uid(),type:"maintenance-restored",routineId:routine.id,title:routine.title,at:now()});persist();render()}}}));document.querySelectorAll("[data-maintenance-id]").forEach(input=>input.addEventListener("change",()=>{const routine=db.maintenanceRoutines.find(item=>item.id===input.dataset.maintenanceId),today=localDate(new Date());if(!routine)return;routine.completedDates=[...new Set((routine.completedDates||[]).filter(date=>date!==today).concat(input.checked?[today]:[]))];routine.lastCompletedAt=input.checked?now():routine.lastCompletedAt;persist();render()}));if(page==="config")addAgendaConfig(db);function bindModal(modal){modal.querySelectorAll("[data-agenda-close]").forEach(button=>button.addEventListener("click",()=>modal.remove()));modal.querySelector("form").addEventListener("submit",event=>{event.preventDefault();const data=new FormData(event.currentTarget),start=data.get("startTime"),end=data.get("endTime"),error=event.currentTarget.querySelector(".form-error");if(minutes(end)<=minutes(start)){error.textContent="O fim precisa ser posterior ao início.";return}const value=Object.fromEntries(data.entries());
if(data.get("repeatWeekly")==="on"){const days=data.getAll("daysOfWeek");if(!days.length)days.push(new Date(`${value.date}T12:00:00`).getDay());const recurrence=saveAgendaRecurrence(db,{...value,name:value.title,daysOfWeek:days,startDate:value.date});value.recurrenceId=recurrence.id;value.originalOccurrenceDate=value.date}
saveAgendaBlock(db,value);persist();modal.remove();render()})}}
export function saveAgendaSettings(db,form){const data=new FormData(form);db.agendaSettings.maximumPlanningOccupancy=Math.max(.6,Math.min(.9,Number(data.get("agendaOccupancy")||75)/100));db.agendaSettings.minimumMarginMinutes=Number(data.get("agendaMargin")||30);db.agendaSettings.minimumFocusMinutes=Number(data.get("agendaFocus")||60);db.agendaSettings.contextSwitchPenalty=Number(data.get("agendaSwitch")||20);Object.keys(RESPONSIBILITY_AREAS).forEach(key=>db.agendaSettings.responsibilities[key].active=data.get(`responsibility-${key}`)==="on")}
export function getAgendaContext(){return activeAgendaContext}
export function clearAgendaContext(){activeAgendaContext=null}
export function augmentAgendaRecommendation(render){if(!activeAgendaContext)return;const main=document.querySelector(".main-content");if(!main||main.querySelector("#agenda-recommendation-context"))return;const banner=document.createElement("section");banner.id="agenda-recommendation-context";banner.className="panel agenda-context-banner";banner.innerHTML=`<div><p class="eyebrow">CONTEXTO DA AGENDA</p><b>${label(RESPONSIBILITY_AREAS,activeAgendaContext.responsibilityArea)}</b><span>${activeAgendaContext.availableMinutes} min disponíveis no bloco</span></div><button class="secondary">Ver tarefas de outras áreas</button>`;banner.querySelector("button").addEventListener("click",()=>{activeAgendaContext=null;render()});main.prepend(banner)}

export function runAgendaTests(){const db={tasks:[],sessions:[],settings:{},scheduleBlocks:[],scheduleRecurrences:[],maintenanceRoutines:[],agendaHistory:[],agendaSettings:null};ensureAgendaData(db);const week=blocksForWeek(db,new Date("2026-08-10T12:00:00"));const mondayBlocks=week.filter(block=>block.date==="2026-08-10");const physio=mondayBlocks.find(block=>block.title==="Fisioterapia");const family=mondayBlocks.find(block=>block.responsibilityArea==="familia");const states=responsibilityStates(db,new Date("2026-08-10T12:00:00"));return {passed:!!physio&&!!family&&states.length===5&&db.maintenanceRoutines.length>=10,weekBlocks:week.length,states:states.map(item=>item.status)}}






